    private static readonly FrozenDictionary<string, XkbKeysymEntry> ByName =
        Entries.ToFrozenDictionary(
            entry => entry.Name,
            entry => new XkbKeysymEntry(entry.Value, entry.Codepoint),
            StringComparer.Ordinal);

    /// <summary>The whole table, keyed by keysym name.</summary>
    public static IReadOnlyDictionary<string, XkbKeysymEntry> All => ByName;

    /// <summary>
    /// Whether the name is a keysym at all. Distinguishes a keysym the model cannot
    /// represent, such as <c>XF86AudioPlay</c>, from text that is not a keysym, which is
    /// the difference between a fidelity report saying "not supported" and "not understood".
    /// </summary>
    public static bool IsKnown(string name) => ByName.ContainsKey(name);

    /// <summary>Gets the Unicode scalar the keysym produces, if it produces one.</summary>
    public static bool TryGetCodepoint(string name, out int codepoint)
    {
        if (ByName.TryGetValue(name, out var entry) && entry.Codepoint != NoCodepoint)
        {
            codepoint = entry.Codepoint;
            return true;
        }

        codepoint = NoCodepoint;
        return false;
    }
}
